import com.luci.pianoroom.MidiParser;import java.util.ArrayList;
public class MidiParserTest{public static void main(String[] a){ArrayList<String> out=new ArrayList<>();MidiParser p=new MidiParser((s,x,y)->out.add(s+":"+x+":"+y));p.accept(new byte[]{(byte)0x90,60},0,2);p.accept(new byte[]{100,61,(byte)0xF8,0},0,4);p.accept(new byte[]{(byte)0xB0,64,127,(byte)0xF0,1,2,(byte)0xF8,3,(byte)0xF7,62,100,(byte)0x80,60,0},0,14);if(!out.toString().equals("[144:60:100, 144:61:0, 176:64:127, 128:60:0]"))throw new AssertionError(out);p.reset();p.accept(new byte[]{60,100},0,2);if(out.size()!=4)throw new AssertionError("reset");p.accept(new byte[]{(byte)0xC3,7,8},0,3);if(!out.get(5).equals("195:8:0"))throw new AssertionError("program");System.out.println("PASS: fragmented messages, running status, real-time interleave, velocity zero, CC64, SysEx discard, reset, single data byte.");}}
